import{$ as e,B as t,et as n,pt as r}from"./chunks/framework.KBYRAceO.js";var i=JSON.parse(`{"title":"키클록 커스터마이징","description":"","frontmatter":{"title":"키클록 커스터마이징","date":"2024-12-21T09:00+09:00","tags":["Keycloak","User Federation"]},"headers":[],"relativePath":"posts/keycloak-customizing.md","filePath":"posts/keycloak-customizing.md","lastUpdated":1787924592000}`),a={name:`posts/keycloak-customizing.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<p>키클록(Keycloak)을 도입하여 통합 인증을 구현하는 경우 기본적인 인증과 인가에 대해서는 해결해주므로 편리할 것 같지만 시스템에서 필요로 하는 모든 요구사항을 커버해주지는 않는다. 일부 시스템에서 요구되는 기능을 처리하고자 하는 경우에는 <a href="https://www.keycloak.org/docs/latest/server_development/" target="_blank" rel="noreferrer">Server Developer Guide</a>를 참고하여 원하는 동작을 수행할 수 있도록 커스터마이징 해야한다.</p><h4 id="키클록-로그인-테마" tabindex="-1">키클록 로그인 테마 <a class="header-anchor" href="#키클록-로그인-테마" aria-label="Permalink to “키클록 로그인 테마”">​</a></h4><p><a href="https://www.keycloakify.dev/" target="_blank" rel="noreferrer">Keycloakify</a>를 통해 직접 프리마커 템플릿을 작성하지 않고서 커스텀 테마를 구성할 수 있는 것 같지만 아무래도 조직에서 리액트를 다루고 있지 않으므로 키클록 테마를 커스터마이징하는 것이 가장 공수가 큰 부분일 것 같다.</p><ul><li><a href="https://www.baeldung.com/spring-keycloak-custom-themes" target="_blank" rel="noreferrer">Customizing Themes for Keycloak</a></li><li><a href="https://www.baeldung.com/keycloak-custom-login-page" target="_blank" rel="noreferrer">Customizing the Login Page for Keycloak</a></li></ul><h4 id="외부-사용자-db를-연동하고자-하는-경우" tabindex="-1">외부 사용자 DB를 연동하고자 하는 경우 <a class="header-anchor" href="#외부-사용자-db를-연동하고자-하는-경우" aria-label="Permalink to “외부 사용자  DB를 연동하고자 하는 경우”">​</a></h4><p>일반적으로 User Federation 을 위해 외부 사용자 DB를 사용할 수 있도록 User Storage SPI 의 <a href="https://www.keycloak.org/docs/latest/server_development/#_user-storage-spi" target="_blank" rel="noreferrer">UserStorageProvider</a>를 구현해야한다. 키클록이 관리하는 <a href="https://www.keycloak.org/docs/latest/server_development/#storage-ids" target="_blank" rel="noreferrer">사용자 식별자 에 대한 형식(Storage Ids)</a>에 대해서 알아야할 것 같다.</p><h4 id="로그인-시-otp-코드를-이메일-또는-sms-로-받으려는-경우" tabindex="-1">로그인 시 OTP 코드를 이메일 또는 SMS 로 받으려는 경우 <a class="header-anchor" href="#로그인-시-otp-코드를-이메일-또는-sms-로-받으려는-경우" aria-label="Permalink to “로그인 시 OTP 코드를 이메일 또는 SMS 로 받으려는 경우”">​</a></h4><p>키클록에서 제공하는 Configure OTP의 경우 TOTP Authenticator를 등록하는 방식으로 진행하기 때문에 OTP 코드를 <a href="https://github.com/mesutpiskin/keycloak-2fa-email-authenticator" target="_blank" rel="noreferrer">이메일</a>, <a href="https://github.com/cooperlyt/keycloak-phone-provider" target="_blank" rel="noreferrer">SMS</a> 또는 카카오 알림톡으로 보내기 위해서는 이에 대한 <a href="https://medium.com/@shreyasmk.mathur/mastering-multi-factor-authentication-in-keycloak-sms-email-and-totp-setup-guide-957305b92be1" target="_blank" rel="noreferrer">Service Provider Interface</a> 를 구현해야한다.</p><h4 id="서비스-애플리케이션에서-otp-또는-패스키-등록" tabindex="-1">서비스 애플리케이션에서 OTP 또는 패스키 등록 <a class="header-anchor" href="#서비스-애플리케이션에서-otp-또는-패스키-등록" aria-label="Permalink to “서비스 애플리케이션에서 OTP 또는 패스키 등록”">​</a></h4><p>키클록의 사용자 콘솔(Account Console)에서 Authenticator 또는 Passkey를 등록하는 것을 서비스 애플리케이션에서 구현하여 수행할 수 있는지는 더 찾아봐야할 것 같다. 만약, 불가능한 경우 키클록 사용자 콘솔에 대한 <a href="https://www.baeldung.com/spring-keycloak-custom-themes" target="_blank" rel="noreferrer">테마를 커스터마이징</a> 할 수 밖에 없을 것 같다.</p><h4 id="사용자-인증-시-새로운-디바이스에-대한-알림을-제공하는-경우" tabindex="-1">사용자 인증 시 새로운 디바이스에 대한 알림을 제공하는 경우 <a class="header-anchor" href="#사용자-인증-시-새로운-디바이스에-대한-알림을-제공하는-경우" aria-label="Permalink to “사용자 인증 시 새로운 디바이스에 대한 알림을 제공하는 경우”">​</a></h4><p><a href="https://www.keycloak.org/docs/latest/server_development/#_events" target="_blank" rel="noreferrer">Event Listener SPI</a>의 EventListenerProvider를 구현하여 로그인 이벤트를 감지하고 인증된 디바이스 세션 정보를 토대로 새로운 디바이스에 대한 알림을 구현할 수 있다. 키클록 자체적으로 신규 발급 여부를 제공해주지는 않으므로 별도의 저장소에 디바이스에 대한 정보를 저장하고 비교하는 방식으로 구현해야할 것 같다.</p>`,12)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};